B=Path(__file__).resolve().parent.parent;arm=int(sys.argv[1]);assert arm in(2,3,4);O=B/('current-read32-arm-%d-preflight-r1'%arm);O.mkdir();root='/opt/vectormatch-cpu/experiments/read-window32-current-abab-r1';gate=B/('current-read32-arm-%d-prior-gate-r1/collection-gate.json'%(arm-1));h=hashlib.sha256(gate.read_bytes()).hexdigest();args=['/usr/bin/python3','-B',root+'/cpu_read_window32_abab.py','--arm',str(arm),'--release-sha256','35652d5dd4175e2f7fff500147ce084a41d9ae7a3c6951b9c67374b780ec05d0','--prior-collection-sha256',h];(O/'REGISTRATION.json').write_text(json.dumps(dict(atUTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),arguments=args,readOnly=True,noStartNewFlag=True),indent=2)+'\n');spec=importlib.util.spec_from_file_location('current_read32_preflight_connection',B/'current-read-window32-collection-preparation-r2/remote_current.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);r=m.run(shlex.join(args),timeout=150);(O/'stdout.json').write_text(r.stdout);(O/'stderr').write_text(r.stderr);(O/'EXECUTION.json').write_text(json.dumps(dict(exitCode=r.returncode,stdoutSha256=hashlib.sha256(r.stdout.encode()).hexdigest(),stderrSha256=hashlib.sha256(r.stderr.encode()).hexdigest()),indent=2)+'\n');assert r.returncode==0;d=json.loads(r.stdout);assert d['passed'] and d['noJavaStarted'] and d['arm']==arm;print(json.dumps(dict(passed=True,arm=arm,readWindow=d['readWindow'],priorArmVerified=d['priorArm']['passed'],noJavaStarted=True)))
